"""One-time documentation reconciliation; leaves application and source geometry untouched."""
from pathlib import Path
import json,re
from collections import Counter

ROOT=Path(__file__).resolve().parents[3]
RUN=Path(__file__).resolve().parent
REPORT='research/stage7-muscle-recovery-2026-10-21.md'
MATRIX='research/stage7-muscle-blockers-2026-10-21'
LOG='LOG-20261021-05'
issues=(ROOT/'ANATOMY_ISSUES.md').read_text(encoding='utf-8-sig')
assert LOG not in issues,'This documentation run has already been applied'
before=json.loads((RUN/'muscle-inventory-before.json').read_text(encoding='utf-8'))
after=json.loads((RUN/'muscle-inventory-after.json').read_text(encoding='utf-8'))
pattern=r'^### ([A-Za-z0-9_-]+)\n(.*?)(?=^### |\Z)'
original={m[1]:m[2] for m in re.finditer(pattern,issues,re.M|re.S)}
rows=[]

def disposition(ident):
    if ident=='MG-palmaris_brevis':
        return ('В действующей сборке/локальных исходниках и просмотренных BP3D-индексах принятой мышцы нет. Найден кандидат Physiome workspace 968 / e/9e5; страницы при проверке вернули 403, модель не получена.',
                'Авторский файл, явная лицензия, сторона и система координат, сопоставление с ладонью. Геометрия другого образца требует регистрации и отдельного допуска.',
                ['https://models.physiomeproject.org/workspace/968','https://models.cellml.org/e/9e5'])
    if ident.startswith('MG-auricularis'):
        return ('Обе стороны отсутствуют в опубликованной сборке. Сохранённый аудит VAP/Z-Anatomy/3DFACE не даёт принятого отдельного меша этой мышцы в системе координат проекта.',
                'Лицензированный индивидуальный меш/сегментация с проверенными границами у основания ушной раковины и регистрацией. При появлении одной принятой стороны допустимость отражения проверять отдельно.',[])
    if ident.startswith('MG-depressor_supercilii'):
        return ('VAP Modern Human Head & Neck содержит имя в авторском списке; полученного проверенного файла нет. Групповые маски 3DFACE не приняты как самостоятельная мышца.',
                'Авторизованное получение конкретного меша и его лицензии, затем форма/сторона/совмещение с corrugator и orbicularis на том же образце. Список автора не подтверждает сетку.',
                ['https://sketchfab.com/3d-models/modern-human-head-neck-model-22dbb37977304b5aab9db083b51026d2'])
    if ident=='MG-transversus_menti':
        return ('Сохранён статус вариабельного образования; принятого самостоятельного исходника нет. Схематические/процедурные формы не подтверждают индивидуальное наличие.',
                'Лицензированный образец с документированным вариантом и маской его границ; не создавать обязательную симметричную копию.',[])
    if ident=='MG-thorax_subcostales':
        return ('В каталогизированных локальных ресурсах и адресных BP3D 3/4 индексах нет принятого мышечного исходника; subcostal artery/vein не приняты за мышцы.',
                'Сегментированные мышечные пучки с номерами рёбер и сторонами, лицензией и положением на внутренней грудной стенке.',[])
    if ident=='MG-thorax_intertransversarii_thoracis':
        return ('Не найден принятый грудной исходник. Найденные FMA71442/71443 относятся к шее и не заменяют грудную группу.',
                'Грудные сегменты и стороны на документированном образце, самостоятельная разметка/сетки, научная проверка вариабельности и регистрация.',[])
    if ident=='MG-thorax_sternalis':
        return ('Карточка варианта сохранена. В проверенных источниках нет принятой геометрии; сам факт термина не делает мышцу обязательной.',
                'Образец с документированным вариантом, стороной/ходом/прикреплениями, разрешённым исходником или сегментацией. Не восстанавливать усреднённой лентой.',[])
    if ident.startswith('MP-orbicularis_oculi'):
        return ('Целая мышца имеется, но отдельная разметка глубокой части/ресничного пучка отсутствует. Грубая сетка целой мышцы не является доказательством этих тонких границ.',
                'Маска соответствующего пучка и анатомические референсы того же образца; масштаб век/границы и отдельный выбор без дублирования общей мышцы.',[])
    if ident.startswith('MP-nasalis'):
        return ('Объединённая nasalis загружается; нет принятой границы поперечной и крыльной частей в текущем меше.',
                'Размеченные границы обеих частей по конкретному образцу и проверка стороны. Деление координатной плоскостью не допущено.',[])
    if ident.startswith('MP-orbicularis_oris'):
        return ('Целая мышца присутствует; самостоятельные краевая и губная части не представлены принятой сегментацией.',
                'Анатомически проверенные маски/пучки в геометрии губ и независимая привязка к исходному мешу; не разрезать по расстоянию от пина.',[])
    if ident.startswith('MP-omohyoid'):
        return ('Правый исходник: основной компонент 27 088 треугольников + артефакт 8; левый: один компонент 26 960. Компоненты не дают двух принятых брюшек.',
                'Граница промежуточного сухожилия, маски верхнего/нижнего брюшка и адресное совмещение с подъязычной костью/лопаткой. Полное имя OBJ не подтверждает разделение.',[])
    if ident.startswith('MP-thorax_diaphragm'):
        return ('Целая диафрагма есть; грудинная/рёберная/поясничная территории не имеют принятых отдельных геометрических меток.',
                'Разметка мышечных территорий и сухожильной границы того же образца, проверка прикреплений; произвольное деление по осям запрещено.',[])
    if ident.startswith('MP-thorax_multifidus'):
        return ('Общий многораздельный ресурс присутствует; принятый отдельный грудной регион/пучки отсутствуют.',
                'Позвонковые уровни и маски пучков в текущем образце; доказать границы грудного поднабора, не использовать прямоугольное отсечение.',[])
    if ident.startswith('MP-thorax_rotatores'):
        return ('Целая группа доступна; нет принятых меток longi/breves по каждому пучку.',
                'Подтверждённые начальный/конечный позвонок каждого пучка и маски двух классов; количество компонентов само по себе недостаточно.',[])
    raise AssertionError(ident)

for entry in before['missing']+before['parts']:
    ident=('MP-'+entry['id']+'-'+entry['part']) if 'part'in entry else 'MG-'+entry['id']
    body=original[ident]
    reason,needed,links=disposition(ident)
    criteria=next(x.removeprefix('- Решение и критерий закрытия: ')for x in body.splitlines()if x.startswith('- Решение и критерий закрытия:'))
    rows.append(dict(issue=ident,structure=entry['id'],part=entry.get('part'),status='заблокирована',wholeModelPresent=entry.get('wholePresent',False),
        sourceAssessment=reason,requiredData=needed,links=links,existingAcceptanceCriterion=criteria,
        recoveryDecision='Не интегрировать: доказательств для сегментации, параметрической реконструкции или зеркального допуска недостаточно.',
        evidence=['research/'+RUN.relative_to(ROOT/'research').as_posix()+'/muscle-inventory-after.json','research/new-muscle-source-audit.json','research/muscle-completion-review.json','research/muscle-reconstruction-review.json'],futureStage='7; независимая финальная приёмка 8'))
assert len(rows)==34 and len({x['issue']for x in rows})==34
matrix=dict(date='2026-10-21',scope='34 исходных экземпляра; отсутствие готового источника не является исчерпывающим доказательством отсутствия во всех коллекциях',
    originalMissingMuscles=13,originalMissingParts=21,rows=rows,
    additional=[dict(issue='ANAT-001',cards=['puborectalis_right','puborectalis_left'],sources=['FMA45856','FMA45857'],decision='Ограниченный учебный допуск; точные контакты, прикрепления, пол и полная научная приёмка открыты'),
                dict(issue='ANAT-002',sources=['FMA71309','FMA71442','FMA71443'],decision='Только пробные GLB; уровни interspinales не подтверждены, межпоперечные сетки имеют дефекты нормалей и неподтверждённые подгруппы')])
with (ROOT/(MATRIX+'.json')).open('x',encoding='utf-8')as f:json.dump(matrix,f,ensure_ascii=False,indent=2)
md=['# Этап 7 — поимённые решения по 34 прежним пробелам','',
    '21.10.2026. Это доказательства к существующим ID, не новый реестр. Критерии закрытия сохранены дословно в [JSON](stage7-muscle-blockers-2026-10-21.json). Две новые puborectalis относятся к ANAT-001 отдельно; исходные 13/21 остаются. [Итоговый отчёт](stage7-muscle-recovery-2026-10-21.md).','',
    '| Постоянный ID | Что установлено | Что нужно для следующей попытки |','|---|---|---|']
md += [f"| {r['issue']} | {r['sourceAssessment']} | {r['requiredData']} |"for r in rows]
md+=['','У всех строк статус «заблокирована». Разделение объединённого меша и отражение отсутствующей/непринятой исходной стороны не выполнены. Параметрическая форма без привязанных к образцу границ не допущена. Старые научные поля этих карточек не переписаны; новая полная научная проверка всех полей 34 структур не заявляется.','']
with (ROOT/(MATRIX+'.md')).open('x',encoding='utf-8')as f:f.write('\n'.join(md))

def amend(match):
    ident,body=match[1],match[2]
    if ident in {r['issue']for r in rows}:
        row=next(r for r in rows if r['issue']==ident)
        body=body.rstrip()+f"\n\n- Дополнение {LOG} (21.10.2026): {row['sourceAssessment']} Для разблокировки: {row['requiredData']} Статус и полный критерий сохранены. [По-ID решения]({MATRIX}.md), [инвентаризация и проверки]({REPORT}).\n\n"
    elif ident=='ANAT-001':
        body=body.replace('Статус: **требует проверки**','Статус: **в работе**',1).replace('Обновлено: **2026-10-15**','Обновлено: **2026-10-21**',1)
        body=body.replace('Структуры и ID: levator_ani, части pubo/ilio; отдельного проектного ID puborectalis нет.','Структуры и ID: levator_ani, части pubo/ilio; с 21.10.2026 puborectalis_right и puborectalis_left — отдельные связанные карточки с учебной геометрией.')
        body=body.replace('- Доказательства исправления и тесты: Научное понятие','- Доказательства исправления и тесты: История 15.10.2026: научное понятие',1)
        body=body.rstrip()+f'\n\n- Дополнение {LOG}: 21.10.2026 статус «требует проверки» → «в работе». Получены FMA45856/45857 из официального архива BP3D 3.0; обе модели подключены с ограниченным учебным допуском и атрибуцией CC BY-SA 2.1 Japan. Самостоятельный выбор, обратные ссылки levator_ani, поиск, стороны, изоляция, прозрачность и BVH проверены. 323 Node / 74 MCP-утверждения, 1280/390 px; Blender/trimesh. Исходные файлы и пины сохранены. Не закрыто: точные границы и площади прикреплений, самопересечения/контакты (выборочная глубина до 1,821 мм справа относительно obturator internus не является полным максимумом), пол исходного образца, отдельная проверка иннервации/кровоснабжения. Нужны сегментация/метаданные образца и независимая анатомическая приёмка. Это две дополнительные структуры, не закрытие двух из 13 MG. [Отчёт]({REPORT}).\n\n'
    elif ident=='ANAT-002':
        body=body.replace('Обновлено: **2026-10-15**','Обновлено: **2026-10-21**',1)
        body=body.replace('- Доказательства исправления и тесты: Отсутствие','- Доказательства исправления и тесты: История 15.10.2026: отсутствие',1)
        body=body.rstrip()+f'\n\n- Дополнение {LOG}: три исходника FMA71309/71442/71443 теперь получены и исследованы; прежнее «файлы не найдены» — исторический результат. Все три остались пробными. Для FMA71309 верхняя пара приближается к дуге атланта, уровни 12 компонентов не приняты; нужны метки C2–C3…C7–T1 по образцу. FMA71442/71443 имеют соответственно 20/19 изолированных двусторонних треугольных пластинок и неопределённые нормали; нужна документированная корректная сетка. У posterior отсутствует подтверждённое разделение mediales/laterales. Автоматическое удаление пластинок, смещение или переименование не выполнены. Нужны лицензированный качественный источник, сегментная разметка, две независимые опоры каждого научного поля и отдельный выбор. NBK557555 не использована как подтверждение четырёх коротких групп: конкретного локатора в ней не найдено. Номенклатура и отношения проверены адресно по TA98/UAMS/Gray, но не заменяют геометрию. [Отчёт]({REPORT}).\n\n'
    return '### '+ident+'\n'+body
issues=re.sub(pattern,amend,issues,flags=re.M|re.S)
issues=issues.replace('| [ANAT-001](#anat-001) | Puborectalis не представлен отдельной частью существующего levator ani | 7 | P1 | требует проверки |','| [ANAT-001](#anat-001) | Puborectalis: отдельные модели и полная приёмка | 7 | P1 | в работе |')
issues=issues.replace('Срез состояния: **2026-10-21**, LOG-20261021-04:','Предыдущий срез: **2026-10-21**, LOG-20261021-04:',1)
intro=f'Срез состояния: **2026-10-21**, {LOG}: этап 7 начат. 255→257 мышечных карточек, 301→303 меша; две puborectalis подключены с ограниченным учебным допуском. Исходные 13 MG / 21 MP и три пробных шейных источника остаются без допуска. ANAT-001 в работе, полная приёмка не закрыта; 20 костных noModel и остатки этапа 6 сохранены. [Отчёт]({REPORT}).\n\n'
issues=issues.replace('# ANATOMY_ISSUES — единый реестр проблем\n\n','# ANATOMY_ISSUES — единый реестр проблем\n\n'+intro,1)
newsummary=f'{LOG}, текущий срез: **254 задачи / 72 проверено / 182 не закрыто** — 30 открыты, 4 в работе, 87 требуют проверки, 61 заблокирована. Закрыто 0, новых ID 0. 323 Node и 74 принятых MCP-утверждения; 2 учебные мышечные модели не закрывают научную/геометрическую приёмку. [Отчёт]({REPORT}).\n\n'
issues=issues.replace('## Сводка\n\n','## Сводка\n\n'+newsummary,1).replace('LOG-20261021-02, текущий срез:','LOG-20261021-02, предыдущий срез:',1)
# Reconcile stale numeric table from the actual cards, including pre-existing VIS transitions.
counts=Counter(re.search(r'Статус: \*\*([^*]+)\*\*',m[2])[1]for m in re.finditer(pattern,issues,re.M|re.S))
assert counts==Counter({'проверена':72,'заблокирована':61,'требует проверки':87,'в работе':4,'открыта':30})
for status in ['открыта','в работе','требует проверки','заблокирована','исправлена','проверена']:
    issues=re.sub(r'^\| '+status+r' \| \d+ \|$',f'| {status} | {counts[status]} |',issues,flags=re.M)
issues=issues.replace('Актуальные числа LOG-20261019-11:', 'Исторические числа LOG-20261019-11:',1)
(ROOT/'ANATOMY_ISSUES.md').write_text(issues,encoding='utf-8')

progress=(ROOT/'ANATOMY_PROGRESS.md').read_text(encoding='utf-8-sig')
progress=re.sub(r'^\| 7 \|.*$', '| 7 | Восстановление 13 мышц и 21 части | В работе: две дополнительные puborectalis подключены | LOG-20261021-05: 257 карточек, 303 меша. 13 MG / 21 MP остаются без геометрии; ANAT-001 учебный допуск, полная приёмка открыта; ANAT-002 — три источника только тестовые. 323 Node / 74 MCP, Blender/trimesh. Записи учёта: 0 проверено / 45 всего; это не процент готовности анатомии. |',progress,flags=re.M)
progress=progress.replace('61 заблокирована; 88 имеют статус «требует проверки»','61 заблокирована; 87 имеют статус «требует проверки»',1)
progress=progress.replace('Открыта: 30; в работе: 3; исправлена без приёмки: 0. Текущий срез LOG-20261021-04','Открыта: 30; в работе: 4; исправлена без приёмки: 0. Текущий срез LOG-20261021-05',1)
progress+=f'''\n\n### {LOG} — мышечная инвентаризация и первая учебная интеграция

Дата: **21.10.2026**. Этап **7**. [Отчёт]({REPORT}), [34 поимённых решения]({MATRIX}.md). История и остатки этапа 6 сохранены; стадия 8 не начата.

- Фактическая инвентаризация: 255→257 мышечных карточек, 301→303 меша; 13 исходных мышц и 21 часть без отдельной геометрии, 0 несогласованных флагов. 20 костных noModel неизменны.
- ANAT-001: получены официальные FMA45856/45857, подключены `puborectalis_right/left` с предупреждением учебной геометрии, атрибуцией и CC BY-SA 2.1 Japan. Общая форма/стороны проверены; точные границы, контакты, индивидуальные параметры и отдельные научные поля не приняты. Статус изменён «требует проверки» → «в работе»; закрытия нет.
- ANAT-002: FMA71309/71442/71443 найдены, но остались тестовыми из-за неподтверждённых сегментных уровней/подгрупп и дефектов нормалей. Файлы не выдаются за завершённую анатомическую сегментацию.
- Добавлен воспроизводимый издатель и ленивый загрузчик дополнительных мышц; обратные связи с levator_ani, существующие ID/модели сохранены. Пины и оригинальные OBJ/GLB не изменены. Зеркальные/произвольные реконструкции не созданы.
- Проверки: Blender (4 вида), trimesh/пять адресных self-intersection прогонов; 323 Node PASS, TA98 762 термина/только 3 прежних расхождения; 74 принятых MCP-утверждения на 1280 light и 390 dark. Финальная чистая страница без тестовой вставки загружает/выбирает новую мышцу. Фазы ограничены 35 секундами, снимки/JSON сохранялись отдельно; ранние ошибки сценария сохранены и не выданы за дефекты продукта.
- Исправлена устаревшая числовая таблица реестра (ранние VIS-статусы уже были изменены в карточках); это сверка счётчика, не новые закрытия.
- За партию **0 закрытых / 0 новых задач**. **254 всего, 72 проверены, 182 не закрыты, 61 заблокирована**; 30 открыты, 4 в работе, 87 требуют проверки. Включены все прежние 34 MG/MP. Число задач отдельно от двух подключённых структур.
- Дальше: разрешённый исходник palmaris brevis (найден новый кандидат Physiome, доступ/лицензия/регистрация не проверены), исправные и сегментно размеченные короткие шейные мышцы, маски брюшек/пучков объединённых ресурсов. Полная приёмка новых puborectalis и DATA-MUSCLE-BONE-LINKS открыты; финальный этап автоматически не запускается.
'''
(ROOT/'ANATOMY_PROGRESS.md').write_text(progress,encoding='utf-8')

status=(ROOT/'CURRENT_PROJECT_STATUS.md').read_text(encoding='utf-8-sig')
status=status.replace('**21.10.2026 · этап 6: геометрия и выделение областей.**','**21.10.2026 · этап 7: первая учебная интеграция мышц.**',1)
